import sys

def solve():
    # Read input from standard input
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = float(line)
    except (EOFError, ValueError):
        return

    # The function f(x) = x^x is strictly increasing for x >= 1.
    # Since 1 <= n <= 10,000,000,000, and 1^1 = 1 and 10^10 = 10,000,000,000,
    # the solution x must be in the range [1, 10].
    low = 1.0
    high = 10.0

    # Binary search to find x such that x^x = n.
    # 100 iterations provide precision far beyond the required 10^-6.
    for _ in range(100):
        mid = (low + high) / 2
        # Calculate mid^mid. Python handles float exponentiation.
        try:
            val = mid**mid
        except OverflowError:
            # In case mid**mid overflows, treat it as greater than n
            val = n + 1

        if val < n:
            low = mid
        else:
            high = mid

    # Print the result with high precision to meet the relative/absolute error requirement.
    print(f"{high:.10f}")

if __name__ == "__main__":
    solve()

