import sys

def solve():
    # Read input from standard input
    line = sys.stdin.readline()
    if not line:
        return

    try:
        # Parse the two integers x and y
        x, y = map(int, line.split())
    except ValueError:
        return

    # The problem asks to compare x^y and y^x.
    # This is equivalent to comparing y * ln(x) and x * ln(y),
    # or comparing ln(x)/x and ln(y)/y.
    # Let f(t) = ln(t)/t. The derivative f'(t) = (1 - ln(t))/t^2.
    # f(t) increases for 0 < t < e and decreases for t > e (e ≈ 2.718).

    if x == y:
        # If x and y are equal, x^y is obviously equal to y^x.
        print('=')
    elif x == 1:
        # 1^y = 1, and y^1 = y. Since y > 1 (because x != y), 1 < y.
        print('<')
    elif y == 1:
        # x^1 = x, and 1^x = 1. Since x > 1 (because x != y), x > 1.
        print('>')
    elif x == 2:
        # Special cases for x = 2:
        # 2^1 = 2, 1^2 = 1 (handled by y == 1)
        # 2^2 = 4, 2^2 = 4 (handled by x == y)
        # 2^3 = 8, 3^2 = 9 (2^3 < 3^2)
        # 2^4 = 16, 4^2 = 16 (2^4 = 4^2)
        # 2^y > y^2 for y >= 5
        if y == 3:
            print('<')
        elif y == 4:
            print('=')
        else:
            print('>')
    elif y == 2:
        # Special cases for y = 2:
        # 1^2 = 1, 2^1 = 2 (handled by x == 1)
        # 2^2 = 4, 2^2 = 4 (handled by x == y)
        # 3^2 = 9, 2^3 = 8 (3^2 > 2^3)
        # 4^2 = 16, 2^4 = 16 (4^2 = 2^4)
        # x^2 < 2^x for x >= 5
        if x == 3:
            print('>')
        elif x == 4:
            print('=')
        else:
            print('<')
    elif x < y:
        # For x, y >= 3, f(t) = ln(t)/t is strictly decreasing.
        # If 3 <= x < y, then f(x) > f(y) => ln(x)/x > ln(y)/y => y*ln(x) > x*ln(y) => x^y > y^x.
        print('>')
    else:
        # If 3 <= y < x, then f(y) > f(x) => ln(y)/y > ln(x)/x => x*ln(y) > y*ln(x) => y^x > x^y.
        print('<')

if __name__ == "__main__":
    solve()

