            # If base > 1, then log(a_i) > 0 and we can compare V = log(log(a_i)).
            if base <= 1.0:
                return -float('inf')

            log_base = math.log(base)
            try:
                if not is_simple_exp:
                    # V = log(exp_base^exp_pow * log(base)) = exp_pow * log(exp_base) + log(log(base))
                    return exp_pow * math.log(exp_base) + math.log(log_base)
                else:
                    # V = log(exp_base * exp_pow * log(base)) = log(exp_base * exp_pow) + log(log(base))
                    return math.log(exp_base * exp_pow) + math.log(log_base)
            except (ValueError, OverflowError):
                return -float('inf')

        # List all 12 options
        vs = [
            get_v(x, y, z, False), # a1: x^y^z
            get_v(x, z, y, False), # a2: x^z^y
            get_v(x, y, z, True),  # a3: (x^y)^z
