import math
import sys

def get_score(base, p_type, p_val1, p_val2):
    """
    Computes a score for the expression L = p * ln(base), where p is either
    p_val1**p_val2 (p_type == 0) or p_val1 * p_val2 (p_type == 1).

    The score is represented as (sign, ln_abs_L).
    sign = 1 if L > 0, 0 if L = 0, -1 if L < 0.
    ln_abs_L = ln(|L|) = ln(p) + ln(|ln(base)|).
    """
    try:
        ln_base = math.log(base)
    except ValueError:
        # base should be > 0 according to the problem (0.1 to 200.0)
        return (0, 0)

    if abs(ln_base) < 1e-13:
        return (0, 0)

    # Calculate ln(p)
    if p_type == 0:
        # p = p_val1 ** p_val2
        # Use math.log for p_val1 since p_val1 is always >= 0.1
        ln_p = p_val2 * math.log(p_val1)
    else:
        # p = p_val1 * p_val2
        ln_p = math.log(p_val1) + math.log(p_val2)

    if ln_base > 0:
        return (1, ln_p + math.log(ln_base))
    else:
        return (-1, ln_p + math.log(-ln_base))

def solve():
    # Read input x, y, z from standard input
    try:
        line = sys.stdin.readline()
        if not line:
            return
        parts = line.split()
        if len(parts) < 3:
            return
        x = float(parts[0])
        y = float(parts[1])
        z = float(parts[2])
    except EOFError:
        return

    # Define the expressions based on the indices provided in the problem.
    # (base, p_type, p_val1, p_val2, expression_string)
    # p_type 0 means p_val1^p_val2, p_type 1 means p_val1*p_val2
    expressions = [
        (x, 0, y, z, "x^y^z"),    # a1 = x^(y^z)
        (x, 0, z, y, "x^z^y"),    # a2 = x^(z^y)
        (x, 1, y, z, "(x^y)^z"),  # a3 = (x^y)^z = x^(y*z)
        (x, 1, z, y, "(x^z)^y"),  # a4 = (x^z)^y = x^(z*y)
        (y, 0, x, z, "y^x^z"),    # a5 = y^(x^z)
        (y, 0, z, x, "y^z^x"),    # a6 = y^(z^x)
        (y, 1, x, z, "(y^x)^z"),  # a7 = (y^x)^z = y^(x*z)
        (y, 1, z, x, "(y^z)^x"),  # a8 = (y^z)^x = y^(z*x)
        (z, 0, x, y, "z^x^y"),    # a9 = z^(x^y)
        (z, 0, y, x, "z^y^x"),    # a10 = z^(y^x)
        (z, 1, x, y, "(z^x)^y"),  # a11 = (z^x)^y = z^(x*y)
        (z, 1, y, x, "(z^y)^x")   # a12 = (z^y)^x = z^(y*x)
    ]

    best_score = None
    best_expr = ""

    for base, p_type, pv1, pv2, expr_str in expressions:
        score = get_score(base, p_type, pv1, pv2)

        if best_score is None:
            best_score = score
            best_expr = expr_str
            continue

        # Compare the current score with the best score
        s1, v1 = score
        s2, v2 = best_score

        is_better = False
        if s1 > s2:
            is_better = True
        elif s1 == s2:
            if s1 == 1:
                # Both positive, larger ln_abs_L is better
                if v1 > v2 + 1e-13:
                    is_better = True
            elif s1 == -1:
                # Both negative, smaller ln_abs_L is better (closer to 0)
                if v1 < v2 - 1e-13:
                    is_better = True
            # if s1 == 0, they are both 0, and we keep the one with the smaller index.

        if is_better:
            best_score = score
            best_expr = expr_str

    # Print the result
    sys.stdout.write(best_expr + "\n")

