import math
import sys

def get_L_info(base, e1, e2, is_pp):
    """
    Computes the sign and log of the absolute value of the logarithm of 
    the expression. L = log(expression).
    If is_pp is False, expression is base^(e1^e2), so L = e1^e2 * log(base).
    If is_pp is True, expression is (base^e1)^e2, so L = e1 * e2 * log(base).
    """
    if abs(base - 1.0) < 1e-9:
        return (0, -float('inf'))

    # The sign of L is the sign of log(base)
    sign = 1 if base > 1.0 else -1

    # We calculate log(|L|) to avoid overflow of L itself.
    # If not is_pp: |L| = e1^e2 * |log(base)|  =>  log|L| = e2 * log(e1) + log|log(base)|
    # If is_pp:     |L| = e1 * e2 * |log(base)| =>  log|L| = log(e1) + log(e2) + log|log(base)|
    try:
        if not is_pp:
            log_abs_L = e2 * math.log(e1) + math.log(abs(math.log(base)))
        else:
            log_abs_L = math.log(e1) + math.log(e2) + math.log(abs(math.log(base)))
    except (ValueError, OverflowError):
        # This handles cases where base, e1, e2 may be values that cause math errors, 
        # though problem constraints 0.1 <= x,y,z <= 200 should prevent this.
        return (sign, -float('inf'))

    return (sign, log_abs_L)

def compare(info1, info2):
    """
    Compares two L values based on their sign and log(|L|).
    Returns 1 if L1 > L2, -1 if L1 < L2, and 0 if L1 == L2.
    """
    sign1, logabs1 = info1
    sign2, logabs2 = info2

    if sign1 > sign2:
        return 1
    if sign1 < sign2:
        return -1

    # If both signs are 0, then L1 = L2 = 0.
    if sign1 == 0:
        return 0

    # If both signs are 1 (L > 0), higher log(|L|) means higher L.
    if sign1 == 1:
        if logabs1 > logabs2 + 1e-13:
            return 1
        if logabs1 < logabs2 - 1e-13:
            return -1
        return 0

    # If both signs are -1 (L < 0), lower log(|L|) means higher L (closer to 0).
    if sign1 == -1:
        if logabs1 < logabs2 - 1e-13:
            return 1
        if logabs1 > logabs2 + 1e-13:
            return -1
        return 0

    return 0

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    x, y, z = map(float, input_data)

    # The 12 expressions described in the problem
    # a1 = x^{y^z}, a2 = x^{z^y}, a3 = (x^y)^z, a4 = (x^z)^y
    # a5 = y^{x^z}, a6 = y^{z^x}, a7 = (y^x)^z, a8 = (y^z)^x
    # a9 = z^{x^y}, a10 = z^{y^x}, a11 = (z^x)^y, a12 = (z^y)^x

    configs = [
        (x, y, z, False), (x, z, y, False), (x, y, z, True), (x, z, y, True),
        (y, x, z, False), (y, z, x, False), (y, x, z, True), (y, z, x, True),
        (z, x, y, False), (z, y, x, False), (z, x, y, True), (z, y, x, True)
    ]

    expr_strings = [
        "x^y^z", "x^z^y", "(x^y)^z", "(x^z)^y",
        "y^x^z", "y^z^x", "(y^x)^z", "(y^z)^x",
        "z^x^y", "z^y^x", "(z^x)^y", "(z^y)^x"
    ]

    best_index = 0
    best_info = get_L_info(*configs[0])

    for i in range(1, 12):
        current_info = get_L_info(*configs[i])
        # We need the smallest index c such that a_c = m.
        # Therefore, only update if current_info is strictly greater than best_info.
        if compare(current_info, best_info) == 1:
            best_info = current_info
            best_index = i

    print(expr_strings[best_index])

