import math
import sys

def solve():
    # Read x, y, z from standard input
    line = sys.stdin.readline()
    if not line:
        return
    try:
        x, y, z = map(float, line.split())
    except ValueError:
        return

    def get_sign(b):
        if b > 1.0 + 1e-9:
            return 1
        if b < 1.0 - 1e-9:
            return -1
        return 0

    def get_val(p, q, b):
        # L = p^q * log(b)
        # log|L| = q * log(p) + log|log(b)|
        # We only call this if abs(log(b)) > 0
        return q * math.log(p) + math.log(abs(math.log(b)))

    def get_val_type_b(p, q, b):
        # L = (p * q) * log(b)
        # log|L| = log(p) + log(q) + log|log(b)|
        return math.log(p) + math.log(q) + math.log(abs(math.log(b)))

    def get_score(p, q, b, type_b=False):
        s = get_sign(b)
        if s == 0:
            return (0, 0.0)
        if type_b:
            v = get_val_type_b(p, q, b)
        else:
            v = get_val(p, q, b)

        if s == 1:
            # For L > 0, score is (1, log L)
            return (1, v)
        else:
            # For L < 0, score is (-1, log(-L))
            # Since L = -e^v, a smaller v means a larger L.
            # To use (sign, value) for maximum, we can store (-1, -v)
            return (-1, -v)

    # Expressions provided in the problem description
    # a1 = x^{y^z}, a2 = x^{z^y}, a3 = (x^y)^z, a4 = (x^z)^y
    # a5 = y^{x^z}, a6 = y^{z^x}, a7 = (y^x)^z, a8 = (y^z)^x
    # a9 = z^{x^y}, a10 = z^{y^x}, a11 = (z^x)^y, a12 = (z^y)^x
    params = [
        (y, z, x, False), # a1
        (z, y, x, False), # a2
        (y, z, x, True),  # a3
        (z, y, x, True),  # a4
        (x, z, y, False), # a5
        (z, x, y, False), # a6
        (x, z, y, True),  # a7
        (z, x, y, True),  # a8
        (x, y, z, False), # a9
        (y, x, z, False), # a10
        (x, y, z, True),  # a11
        (y, x, z, True),  # a12
    ]

    labels = [
        "x^y^z", "x^z^y", "(x^y)^z", "(x^z)^y",
        "y^x^z", "y^z^x", "(y^x)^z", "(y^z)^x",
        "z^x^y", "z^y^x", "(z^x)^y", "(z^y)^x"
    ]

    scores = []
    for p, q, b, type_b in params:
        scores.append(get_score(p, q, b, type_b))

    def compare_scores(s1, s2):
        # Returns 1 if s1 > s2, -1 if s1 < s2, 0 if equal
        if s1[0] != s2[0]:
            return 1 if s1[0] > s2[0] else -1
        if s1[0] == 0:
            return 0
        if s1[1] > s2[1] + 1e-11:
            return 1
        if s1[1] < s2[1] - 1e-11:
            return -1
        return 0

    best_idx = 0
    for i in range(1, 12):
        if compare_scores(scores[i], scores[best_idx]) > 0:
            best_idx = i

    print(labels[best_idx])

