    points = []
    for i in range(N):
        points.append((int(input_data[2*i+1]), int(input_data[2*i+2])))

    MOD = 998244353

    # Cross product of vectors (p1-p0) and (p2-p0)
    def cross_product(p0, p1, p2):
        return (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0])

    # Precompute powers of 2
    pow2 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    total_ans = 0

    for p0_idx in range(N):
        p0 = points[p0_idx]
        p_above = []
        for i in range(N):
            if i == p0_idx:
                continue
            pi = points[i]
            # Sort by y-coordinate, then by x-coordinate
            if pi[1] > p0[1] or (pi[1] == p0[1] and pi[0] > p0[0]):
                p_above.append(pi)

        # Sort p_above by angle around p0
        # Using atan2 is sufficient for N=200
        import math
        p_above.sort(key=lambda p: math.atan2(p[1] - p0[1], p[0] - p0[0]))

        m = len(p_above)
        if m < 2:
            continue

        # precompute counts for W(i, j) and edges on P0Pi
        # w[i][j] = points strictly inside triangle P0 Pi Pj or on edge Pi Pj
        w = [[0] * m for _ in range(m)]
        # b[i] = points on segment P0 Pi excluding P0 and Pi
        b = [0] * m
        for i in range(m):
            pi = p_above[i]
            for k in range(m):
                if k == i: continue
                pk = p_above[k]
                if cross_product(p0, pi, pk) == 0:
                    # P0, Pi, Pk are collinear. Check if Pk is between P0 and Pi.
                    # Since they are sorted by angle, this is easier:
                    # we only need to check if distance(P0, Pk) < distance(P0, Pi)
                    if (pk[0]-p0[0])*(pi[0]-p0[0]) >= 0 and (pk[1]-p0[1])*(pi[1]-p0[1]) >= 0:
                        if abs(pk[0]-p0[0]) < abs(pi[0]-p0[0]) or abs(pk[1]-p0[1]) < abs(pi[1]-p0[1]):
                            b[i] += 1

        for i in range(m):
            pi = p_above[i]
            for j in range(i + 1, m):
                pj = p_above[j]
                # P0, Pi, Pj are already in counter-clockwise order if sorted by angle
                # Check if P0, Pi, Pj is a strict left turn
                if cross_product(p0, pi, pj) > 0:
                    count = 0
                    for k in range(m):
                        if k == i or k == j: continue
                        pk = p_above[k]
                        # P is inside P0 Pi Pj or on edge Pi Pj if:
                        # P is strictly to the left of P0 Pi, strictly to the left of Pj P0, 
                        # and to the left of or on Pi Pj.
                        if cross_product(p0, pi, pk) > 0 and cross_product(p0, pj, pk) < 0 and cross_product(pi, pj, pk) >= 0:
                            count += 1
                    w[i][j] = count

        # dp[i][j] = sum of scores for chains ending in edge Pi Pj
        dp = [[0] * m for _ in range(m)]
        for j in range(m):
            # The chain P0, Pj is not a polygon, but it's the starting point for dp[i][j]
            # Let's initialize dp[i][j] for triangles P0, Pi, Pj
            for i in range(j):
                if cross_product(p0, p_above[i], p_above[j]) > 0:
                    # S = {P0, Pi, Pj}, score = 2^(W(i,j) + b[i] + b[j])
                    # The DP stores the part excluding 2^b[j]
                    score_part = (pow2[b[i]] * pow2[w[i][j]]) % MOD
                    dp[i][j] = (dp[i][j] + score_part) % MOD

                    # Now extend this to more points: P0, ..., Pk, Pi, Pj
                    # This part should actually be in a separate loop to ensure dependency
                    # But wait, since we iterate j then i then k, it works.

        # The nested loop for DP should be ordered carefully
        dp = [[0] * m for _ in range(m)]
        for j in range(m):
            for i in range(j):
                if cross_product(p0, p_above[i], p_above[j]) > 0:
                    # Triangle case: P0, Pi, Pj
                    val = (pow2[b[i]] * pow2[w[i][j]]) % MOD

                    # Extension case: P0, ..., Pk, Pi, Pj
                    for k in range(i):
                        if cross_product(p_above[k], p_above[i], p_above[j]) > 0:
                            val = (val + dp[k][i] * pow2[w[i][j]]) % MOD

                    dp[i][j] = val
                    # Closing the polygon P0, ..., Pi, Pj
                    if cross_product(p_above[i], p_above[j], p0) > 0:
                        total_ans = (total_ans + val * pow2[b[j]]) % MOD

    print(total_ans % MOD)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read n
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    if not a:
        return

    # Maximum possible value of a_i is 100,000
    M = 100000
    MOD = 10**9 + 7

    # Sieve to calculate the Mobius function mu
    mu = [0] * (M + 1)
    mu[1] = 1
    primes = []
    is_prime = [True] * (M + 1)
    for i in range(2, M + 1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > M:
                break
            is_prime[i * p] = False
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]

    # Calculate the frequency of each number in the input array
    freq = [0] * (M + 1)
    for x in a:
        freq[x] += 1

    # Count how many elements in the original array are multiples of d
    # The complexity of this step is O(M log M)
    count = [0] * (M + 1)
    for d in range(1, M + 1):
        for multiple in range(d, M + 1, d):
            count[d] += freq[multiple]

    # Precompute powers of 2 modulo 10^9 + 7
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    # The number of coprime subsequences is given by f(1) = sum_{d=1 to M} mu(d) * (2^count(d) - 1)
    ans = 0
    for d in range(1, M + 1):
        if mu[d] == 0:
            continue

        # Number of non-empty subsequences whose GCD is a multiple of d
        g_d = (pow2[count[d]] - 1)

        if mu[d] == 1:
            ans = (ans + g_d) % MOD
        else:
            ans = (ans - g_d) % MOD

    # Ensure the answer is positive
    print(ans % MOD)

