def solve():
    # Use fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    if not a:
        return

    MOD = 10**9 + 7
    M = 100000

    # Find the maximum element in the array to optimize range
    max_a = 0
    for x in a:
        if x > max_a:
            max_a = x

    # Frequency array for elements in a
    freq = [0] * (max_a + 1)
    for x in a:
        freq[x] += 1

    # Precompute Möbius function using a linear sieve
    mu = [0] * (max_a + 1)
    mu[1] = 1
    primes = []
    is_prime = [True] * (max_a + 1)
    for i in range(2, max_a + 1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > max_a:
                break
            is_prime[i * p] = False
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]

    # Precompute powers of 2 modulo 10^9 + 7
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    # f(1) = Sum_{k=1}^M mu(k) * (2^{count(k)} - 1)
    # count(k) is the number of elements in a that are multiples of k
    ans = 0
    for k in range(1, max_a + 1):
        if mu[k] == 0:
            continue

        # Efficiently calculate count(k) using slicing and sum
        # freq[k::k] gives elements freq[k], freq[2k], freq[3k]...
        ck = sum(freq[k::k])

        if ck == 0:
            continue

        term = pow2[ck] - 1
        if mu[k] == 1:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term) % MOD

    # The result should be positive modulo 10^9 + 7
    print(ans % MOD)

