import sys

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])
    s = input_data[2]

    MOD = 10**9 + 7

    def matrix_mult(A, B, size):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            for k_idx in range(size):
                if Ai[k_idx] == 0:
                    continue
                Bk = B[k_idx]
                val_Ai_k = Ai[k_idx]
                for j in range(size):
                    C[i][j] = (C[i][j] + val_Ai_k * Bk[j]) % MOD
        return C

    def matrix_pow(A, p, size):
        res = [[0] * size for _ in range(size)]
        for i in range(size):
            res[i][i] = 1
        while p > 0:
            if p % 2 == 1:
                res = matrix_mult(res, A, size)
            A = matrix_mult(A, A, size)
            p //= 2
        return res

    def get_g(q, s, k):
        if q == 0:
            return 1

        size = 1 << q
        # Precompute all tuples of length q with XOR sum 0
        tuples_xor_zero = []
        for i in range(1 << (q - 1)):
            t = [(i >> j) & 1 for j in range(q - 1)]
            xor_sum = 0
            for x in t:
                xor_sum ^= x
            t.append(xor_sum)
            tuples_xor_zero.append(t)

        # Build T_0 and T_1
        # T_0 is diagonal
        T0 = [[0] * size for _ in range(size)]
        for mask in range(size):
            ones = bin(mask).count('1')
            T0[mask][mask] = pow(2, max(0, ones - 1), MOD) if q > 0 else 1
            # Wait, if q=0, this is a special case. But q >= 1 here.
            if ones == 0:
                # all x_j must be 0, XOR sum is 0. Only 1 way.
                T0[mask][mask] = 1
            else:
                T0[mask][mask] = pow(2, ones - 1, MOD)

        # T_1
        T1 = [[0] * size for _ in range(size)]
        for mask in range(size):
            for t in tuples_xor_zero:
                # Check compatibility with b=1: mask_j=1 or x_j <= 1 (always true)
                # The only constraint is when mask_j=0, x_j must be 0 or 1.
                # The new mask mask'_j:
                # if mask_j=1, mask'_j=1
                # if mask_j=0, mask'_j=1 if x_j=0, mask'_j=0 if x_j=1
                new_mask = 0
                for j in range(q):
                    if (mask >> j) & 1:
                        new_mask |= (1 << j)
                    else:
                        if t[j] == 0:
                            new_mask |= (1 << j)
                T1[mask][new_mask] = (T1[mask][new_mask] + 1) % MOD

        # Compute M_s = T_{s0} * T_{s1} * ... * T_{s(L-1)}
        M_s = [[0] * size for _ in range(size)]
        for i in range(size):
            M_s[i][i] = 1

        for char in s:
            if char == '0':
                M_s = matrix_mult(M_s, T0, size)
            else:
                M_s = matrix_mult(M_s, T1, size)

        M_k = matrix_pow(M_s, k, size)
        return sum(M_k[0]) % MOD

    # Compute g(q, R) for all q from 1 to n
    g_vals = {}
    for q in range(1, n + 1):
        g_vals[q] = get_g(q, s, k)

    # Calculate R mod MOD
    L = len(s)
    val_s = int(s, 2) % MOD
    # R = val_s * ( (2^L)^k - 1 ) / (2^L - 1)
    two_L_k = pow(2, L * k, MOD)
    two_L_minus_1_inv = pow(pow(2, L, MOD) - 1, MOD - 2, MOD)
    # If 2^L - 1 is a multiple of MOD, this fails. But L <= 50 and MOD = 10^9+7.
    R_mod = (val_s * (two_L_k - 1) * two_L_minus_1_inv) % MOD

    # Partitions of {1, ..., n}
    def get_partitions(elems):
        if not elems:
            yield []
            return
        first = elems[0]
        rest = elems[1:]
        for p in get_partitions(rest):
            # Add first to each block
            for i in range(len(p)):
                yield p[:i] + [[first] + p[i]] + p[i+1:]
            # Add first as a new block
            yield [[first]] + p

    total_f = 0
    import math

    for pi in get_partitions(list(range(n))):
        m = len(pi)
        q = 0
        mu = 1
        for block in pi:
            size_b = len(block)
            if size_b % 2 == 1:
                q += 1
            mu = (mu * ((-1)**(size_b - 1)) * math.factorial(size_b - 1)) % MOD

        if q == 0:
            W = pow(R_mod, m, MOD)
        else:
            W = (pow(R_mod, m - q, MOD) * g_vals[q]) % MOD

        total_f = (total_f + mu * W) % MOD

    # Result is total_f / n!
    inv_n_fact = pow(math.factorial(n), MOD - 2, MOD)
    print((total_f * inv_n_fact) % MOD)

