import sys
from collections import Counter

def solve():
    # Use a generator to read input to handle large inputs efficiently
    def get_input():
        for line in sys.stdin:
            for word in line.split():
                yield word

    input_gen = get_input()

    try:
        n_str = next(input_gen)
    except StopIteration:
        return

    n = int(n_str)
    try:
        m_str = next(input_gen)
    except StopIteration:
        # This case should not happen based on the problem description
        return

    m = int(m_str)

    # switch_vectors[i] will store the state of switch i across all m photos
    # light_vectors[k] will store the state of light k across all m photos
    switch_vectors = [''] * n
    light_vectors = [''] * n

    for _ in range(m):
        try:
            s_string = next(input_gen)
            l_string = next(input_gen)
        except StopIteration:
            break

        for i in range(n):
            switch_vectors[i] += s_string[i]
            light_vectors[i] += l_string[i]

    # Count the occurrences of each unique binary vector for switches and lights
    s_counts = Counter(switch_vectors)
    l_counts = Counter(light_vectors)

    # For a consistent wiring to exist, the distribution of vectors must be identical
    if s_counts != l_counts:
        print(0)
        return

    MOD = 1000003
    ans = 1

    # Precompute factorials modulo 1000003
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # The number of consistent permutations is the product of the factorials
    # of the counts of each unique vector.
    for count in s_counts.values():
        ans = (ans * fact[count]) % MOD

    print(ans)

if __name__ == '__main__':
    solve()

