import sys

def solve():
    # Read all input at once and split into a list of tokens
    try:
        input_data = sys.stdin.read().split()
    except EOFError:
        return

    if not input_data:
        return

    # First token is n (number of switches/lights), second is m (number of photos)
    n = int(input_data[0])
    m = int(input_data[1])

    switches = []
    lights = []

    # Read binary strings for each photo
    idx = 2
    for _ in range(m):
        if idx + 1 < len(input_data):
            switches.append(input_data[idx])
            lights.append(input_data[idx + 1])
            idx += 2

    # Handle the case where there are no photos (m=0)
    if m == 0:
        countS = {"": n}
        countL = {"": n}
    else:
        # For each switch i, the vector Vi is the sequence of its states across m photos.
        # Transpose the list of strings to get vectors for each switch/light efficiently.
        # zip(*switches) unpacks the m switch strings and groups the i-th character of each string.
        switches_transposed = ["".join(col) for col in zip(*switches)]
        countS = {}
        for vec in switches_transposed:
            countS[vec] = countS.get(vec, 0) + 1

        lights_transposed = ["".join(col) for col in zip(*lights)]
        countL = {}
        for vec in lights_transposed:
            countL[vec] = countL.get(vec, 0) + 1

    # The total number of permutations consistent with the photos is the product 
    # of factorials of the counts of each unique vector, provided counts match.
    if countS != countL:
        print(0)
        return

    MOD = 1000003

    # Precompute factorials modulo 1000003
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    ans = 1
    for count in countS.values():
        ans = (ans * fact[count]) % MOD

    # Print the final result
    sys.stdout.write(str(ans) + '\n')

