import sys

def solve():
    # Set recursion limit for deep suffix link trees
    sys.setrecursionlimit(1000000)

    # Read input
    s = sys.stdin.readline().strip()
    if not s:
        print(0)
        return

    n = len(s)

    # Palindromic Tree construction
    # node 0: root of even length palindromes, len = 0, link = 1
    # node 1: root of odd length palindromes, len = -1, link = 1
    lens = [0, -1]
    links = [1, 1]
    next_nodes = [{}, {}]

    last = 0

    # Store the node of the longest palindrome ending at each position
    last_pos_nodes = [0] * n

    for i in range(n):
        char = s[i]
        # Find the longest palindrome ending at i
        while True:
            l = lens[last]
            if i - 1 - l >= 0 and s[i - 1 - l] == char:
                break
            last = links[last]

        if char in next_nodes[last]:
            last = next_nodes[last][char]
        else:
            # Create new node
            new_node = len(lens)
            lens.append(lens[last] + 2)
            next_nodes.append({})

            if lens[new_node] == 1:
                links.append(0)
            else:
                # Find the suffix link for the new node
                tmp = links[last]
                while True:
                    l_tmp = lens[tmp]
                    if i - 1 - l_tmp >= 0 and s[i - 1 - l_tmp] == char:
                        break
                    tmp = links[tmp]
                links.append(next_nodes[tmp][char])

            next_nodes[last][char] = new_node
            last = new_node

        last_pos_nodes[i] = last

    num_nodes = len(lens)
    occ = [set() for _ in range(num_nodes)]
    for i in range(n):
        occ[last_pos_nodes[i]].add(i)

    ans = 0

    # To merge sets small-to-large, we process the suffix link tree bottom-up.
    # In a palindromic tree, link[u] < u is always true for u >= 2.
    for u in range(num_nodes - 1, 1, -1):
        L_u = lens[u]
        # We only care about palindromes P of even length.
        # Check internal occurrences in the initial set occ[u]
        if L_u % 2 == 0:
            sorted_pos = sorted(list(occ[u]))
            for j in range(len(sorted_pos) - 1):
                if sorted_pos[j+1] - sorted_pos[j] == L_u:
                    if 2 * L_u > ans:
                        ans = 2 * L_u
                    break

        # Merge current node's occurrences into its suffix link ancestor
        v = links[u]
        if v < 2:
            continue

        L_v = lens[v]
        if L_v % 2 == 0:
            # Small-to-large merge to maintain O(N log N) complexity
            if len(occ[u]) < len(occ[v]):
                for pos in occ[u]:
                    if (pos + L_v in occ[v]) or (pos - L_v in occ[v]):
                        if 2 * L_v > ans:
                            ans = 2 * L_v
                occ[v].update(occ[u])
            else:
                for pos in occ[v]:
                    if (pos + L_v in occ[u]) or (pos - L_v in occ[u]):
                        if 2 * L_v > ans:
                            ans = 2 * L_v
                occ[u].update(occ[v])
                occ[v] = occ[u]
        else:
            # If L_v is odd, we still need to merge the positions
            if len(occ[u]) < len(occ[v]):
                occ[v].update(occ[u])
            else:
                occ[u].update(occ[v])
                occ[v] = occ[u]

    print(ans)

if __name__ == "__main__":
    solve()
